def _red(r) -> bool:
    out = r.stdout + r.stderr
    return (r.returncode != 0 and "\nFAIL: " in "\n" + out
            and "FAILED (failures=" in out)


def _clear() -> None:
    for d in pathlib.Path("router").rglob("__pycache__"):
        shutil.rmtree(d, ignore_errors=True)


def main() -> int:
    os.environ["PYTHONDONTWRITEBYTECODE"] = "1"
    ok = True
    _clear()
    named = sorted({t for _label, _edits, tests in M for t in tests})
    clean = subprocess.run([sys.executable, "-B", "-m", "unittest", *named],
                           capture_output=True, text=True)
    if clean.returncode != 0:
        print("the named tests are not green on unmutated code:\n" + clean.stderr[-2000:])
        return 1
    for label, edits, tests in M:
        origs = {}
        missing = False
        for f, old, new in edits:
            path = pathlib.Path(f)
            origs.setdefault(f, path.read_text())
            text = path.read_text()
            if text.count(old) != 1:
                print(f"{label}: ANCHOR FOUND {text.count(old)} TIMES in {f}")
                missing = True
                break
            path.write_text(text.replace(old, new))
        try:
            if missing:
                ok = False
                continue
            _clear()
            for t in tests:
                r = subprocess.run([sys.executable, "-B", "-m", "unittest", t],
                                   capture_output=True, text=True)
                red = _red(r)
                ok &= red
                verdict = "RED" if red else ("ERROR only (not RED)" if r.returncode
                                             else "GREEN (survived)")
                print(f"{label[:58]:58s} {t.split('.')[-1][:58]}: {verdict}")
        finally:
            for f, text in origs.items():
                pathlib.Path(f).write_text(text)
    print(f"{len(M)} mutants: " + ("ALL RED" if ok else "SOME SURVIVED OR MISSING"))
    return 0 if ok else 1


if __name__ == "__main__":
    sys.exit(main())
